// Stablecoin contract addresses (1:1 USD, no price feed needed)
const STABLECOINS = {
  '0xdac17f958d2ee523a2206206994597c13d831ec7': { symbol: 'USDT', decimals: 6 },
  '0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48': { symbol: 'USDC', decimals: 6 },
  '0x6b175474e89094c44da98b954eedeac495271d0f': { symbol: 'DAI',  decimals: 18 },
};

const cutoff = Math.floor(Date.now() / 1000) - 14400;
const priceResult = $node['Fetch ETH Price'].json.result || {};
const ethPrice = parseFloat(priceResult.ethusd || '2000');

const seen = new Set();
const events = [];

// Helper to add an event (dedup by hash+symbol)
function addEvent(ev) {
  const key = ev.transaction_hash + ev.symbol;
  if (seen.has(key)) return;
  seen.add(key);
  events.push(ev);
}

// --- Native ETH transfers ---
const ethWallets = [
  { name: 'Coinbase', data: $node['Fetch Coinbase ETH Txns'].json },
  { name: 'Binance',  data: $node['Fetch Binance ETH Txns'].json },
  { name: 'Kraken',   data: $node['Fetch Kraken ETH Txns'].json },
];

for (const wallet of ethWallets) {
  const txns = Array.isArray(wallet.data.result) ? wallet.data.result : [];
  for (const tx of txns) {
    const ts = parseInt(tx.timeStamp, 10);
    if (ts < cutoff) continue;
    if (tx.isError === '1') continue;
    const amountEth = parseFloat(tx.value) / 1e18;
    const amountUsd = amountEth * ethPrice;
    if (amountUsd < 1000000) continue;
    addEvent({
      transaction_hash: tx.hash,
      symbol: 'ETH',
      amount: amountEth,
      amount_usd: Math.round(amountUsd),
      timestamp: new Date(ts * 1000).toISOString(),
      from_owner_type: 'exchange',
      to_owner_type: 'unknown',
      blockchain: 'ethereum',
      from_address: tx.from,
      to_address: tx.to,
      alert_type: 'large_transfer',
      url: 'https://etherscan.io/tx/' + tx.hash,
      source_wallet: wallet.name,
    });
  }
}

// --- Stablecoin (ERC-20) transfers ---
const tokenWallets = [
  { name: 'Coinbase', data: $node['Fetch Coinbase Token Txns'].json },
  { name: 'Binance',  data: $node['Fetch Binance Token Txns'].json },
  { name: 'Kraken',   data: $node['Fetch Kraken Token Txns'].json },
];

for (const wallet of tokenWallets) {
  const txns = Array.isArray(wallet.data.result) ? wallet.data.result : [];
  for (const tx of txns) {
    const ts = parseInt(tx.timeStamp, 10);
    if (ts < cutoff) continue;
    const contract = (tx.contractAddress || '').toLowerCase();
    const stable = STABLECOINS[contract];
    if (!stable) continue;
    const amount = parseFloat(tx.value) / Math.pow(10, stable.decimals);
    const amountUsd = amount; // 1:1 for stablecoins
    if (amountUsd < 1000000) continue;
    addEvent({
      transaction_hash: tx.hash,
      symbol: stable.symbol,
      amount: amount,
      amount_usd: Math.round(amountUsd),
      timestamp: new Date(ts * 1000).toISOString(),
      from_owner_type: 'exchange',
      to_owner_type: 'unknown',
      blockchain: 'ethereum',
      from_address: tx.from,
      to_address: tx.to,
      alert_type: 'large_transfer',
      url: 'https://etherscan.io/tx/' + tx.hash,
      source_wallet: wallet.name,
    });
  }
}

events.sort((a, b) => b.amount_usd - a.amount_usd);

return [{ json: { schema_version: 1, events, count: events.length, eth_price: ethPrice } }];

const events = $json.events || [];
const top = events[0];
const usd = top.amount_usd >= 1000000000
  ? '$' + (top.amount_usd / 1e9).toFixed(1) + 'B'
  : '$' + (top.amount_usd / 1e6).toFixed(1) + 'M';
const amt = top.symbol === 'ETH'
  ? top.amount.toFixed(0) + ' ETH'
  : '$' + (top.amount_usd / 1e6).toFixed(1) + 'M ' + top.symbol;
const tweet = `WHALE ALERT\n${amt} (${usd}) moved from ${top.source_wallet} hot wallet\n\n${top.url}\n\n#${top.symbol} #CryptoWhales #OnChain #AlphaForgeAI`;
return [{ json: { tweet, event: top } }];
